            data.mixX = input2.readFloat();
          if ((flags & 8) != 0)
            data.mixY = input2.readFloat();
          if ((flags & 16) != 0)
            data.mixScaleX = input2.readFloat();
          if ((flags & 32) != 0)
            data.mixScaleY = input2.readFloat();
