            if (!region)
              return null;
            region.path = path;
            region.x = x2 * scale;
            region.y = y * scale;
            region.scaleX = scaleX;
            region.scaleY = scaleY;
            region.rotation = rotation;
            region.width = width * scale;
            region.height = height * scale;
            Color2.rgba8888ToColor(region.color, color);
            region.sequence = sequence;
