    mode: external_exports.enum(["follow", "trail"]).default("follow"),
    startTime: external_exports.number().min(0).optional().describe("one-shot effects: start time in the animation (s)"),
    inheritRotation: external_exports.boolean().optional().describe("default true; false keeps the effect upright while the bone rotates"),
    inheritScale: external_exports.boolean().optional().describe("default true"),
